function filtered(){return nodes.filter(n=>(!type||n.type===type)&&(!decade||n.year&&Math.floor(n.year/10)*10===+decade)&&(!query||[...Object.values(n.labels||{}),...(n.aliases||[])].join(' ').normalize('NFKC').toLowerCase().includes(query.normalize('NFKC').toLowerCase())))}
function select(id){stopRotation();selected=id;query=type=decade='';document.querySelector('#search').value='';view='graph';document.body.classList.add('detail-open');document.body.classList.remove('index-open');$('#index-toggle').setAttribute('aria-expanded','false');render()}
