function render(){document.body.dataset.view=view;$('#index-toggle').textContent=t('searchIndex');$('#close-detail').textContent=t('close');$('#rotation-toggle').textContent=t(autoRotate?'pauseRotation':'rotate');$('#rotation-toggle').setAttribute('aria-pressed',String(autoRotate));document.documentElement.lang={zh:'zh-CN',en:'en',ja:'ja'}[lang];document.title='City Pop Atlas · '+t('nav')[view==='graph'?0:view==='catalog'?1:2];$('#nav').innerHTML=t('nav').map((x,i)=>`<button data-view="${['graph','catalog','guide'][i]}" class="${view===['graph','catalog','guide'][i]?'active':''}">${x}</button>`).join('');$$('#nav [data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',String(b.dataset.lang===lang))});$('#heading').textContent=t('heading');$('#subtitle').textContent=t('subtitle');$('#search').placeholder=t('search');$('#search').setAttribute('aria-label',t('search'));$('#type').innerHTML=['',...new Set(nodes.map(n=>n.type))].map(k=>`<option value="${k}">${k?t(k):t('all')}</option>`).join('');$('#type').value=type;$('#type').setAttribute('aria-label',t('all'));$('#decade').innerHTML=`<option value="">${t('allYears')}</option>`+[...new Set(nodes.filter(n=>n.year).map(n=>Math.floor(n.year/10)*10))].sort().map(y=>`<option value="${y}">${y}s</option>`).join('');$('#decade').value=decade;$('#decade').setAttribute('aria-label',t('allYears'));$('#clear').textContent=t('clear');$('#reset').textContent=t('reset');$('#graph-hint').textContent=t('hint');$('#graph').setAttribute('aria-label',t('hint'));$('#zoom-in').setAttribute('aria-label',({zh:'放大',en:'Zoom in',ja:'拡大'})[lang]);$('#zoom-out').setAttribute('aria-label',({zh:'缩小',en:'Zoom out',ja:'縮小'})[lang]);$('#discover-title').textContent=t('discover');$('#footer-note').textContent=t('footer');$('#about-link').textContent=t('about');$('#results-title').textContent=t('results');$('#catalog-title').textContent=t('catalog');$('#empty').textContent=t('empty');$('#stats').innerHTML=`<div><strong>${nodes.length}</strong><span>${t('nodes')}</span></div><div><strong>${edges.length}</strong><span>${t('edges')}</span></div><div><strong>3</strong><span>中文 / EN / 日本語</span></div>`;$('#legend').innerHTML=Object.entries(colors).map(([k,c])=>`<span><i class="dot" style="background:${c}"></i>${t(k)}</span>`).join('');$('#explore').hidden=view!=='graph';$('#catalog').hidden=view!=='catalog';$('#guide').hidden=view!=='guide';$('#result-section').hidden=view!=='graph';$('.toolbar').hidden=view==='guide';const list=filtered();$('#results-count').textContent=`${list.length} ${t('nodes')}`;$('#catalog-count').textContent=`${list.length} ${t('nodes')}`;$('#results').innerHTML=list.map(n=>`<button class="result ${n.id===selected?'selected':''}" aria-pressed="${n.id===selected}" data-id="${n.id}"><i class="dot" style="background:${colors[n.type]}"></i><strong>${esc(label(n))}</strong><small>${n.year||t(n.type)}</small></button>`).join('')||`<p>${t('empty')}</p>`;$('#cards').innerHTML=list.map(n=>`<button class="card" data-id="${n.id}"><small style="color:${colors[n.type]}">${t(n.type)}${n.year?' / '+n.year:''}</small><h3>${esc(label(n))}</h3><p>${esc(n.labels?.ja||'')}</p></button>`).join('')||`<p>${t('empty')}</p>`;let sug=nodes.filter(n=>['山下達郎','大貫妙子','竹内まりや','松原みき','杏里'].includes(n.labels?.ja)).slice(0,4);$('#suggestions').innerHTML=sug.map(n=>`<button class="chip" data-id="${n.id}">${esc(label(n))}</button>`).join('');$$('[data-id]').forEach(b=>b.onclick=()=>select(b.dataset.id));renderDetail();renderGuide();if(view==='graph')requestAnimationFrame(layout)}
function renderDetail(){let n=index.get(selected);if(!n){$('#detail').innerHTML='';$('#graph-title').textContent=({zh:'音乐的连接',en:'A constellation of music',ja:'音楽のつながり'})[lang];return;}$('#graph-title').textContent=label(n);const rel=edges.filter(e=>e.source===n.id||e.target===n.id);$('#detail').innerHTML=`<div class="type-tag"><span>${t(n.type)}</span><span class="mono">ENTRY</span></div><h2>${esc(label(n))}</h2><div class="original">${esc([...new Set([n.labels?.ja,n.labels?.en])].filter(x=>x&&x!==label(n)).join(' · '))}</div>${n.year?`<div class="year">${n.year}</div>`:''}<p>${esc(desc(n))}</p><h3>${t('connections')} · ${rel.length}</h3>${rel.map(e=>{const other=index.get(e.source===n.id?e.target:e.source);return other?`<button class="relation" data-related="${other.id}"><i class="dot" style="background:${colors[other.type]}"></i><span>${esc(label(other))}</span><small>${t(e.type)}</small></button>`:''}).join('')}<p class="meta-note">${t('unknown')}</p><h3>${t('sources')}</h3>${nodeSources(n).map((url,i)=>`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${i+1}. ${esc(new URL(url).hostname.replace('www.',''))}</a>`).join('')}<p class="meta-note">${t('focus')}</p>`;$$('[data-related]').forEach(b=>b.onclick=()=>select(b.dataset.related))}
function renderGuide(){const content={zh:`<h2>City Pop 没有一条固定的边界</h2><p>City Pop 通常用来讨论日本 1970 年代后期至 1980 年代具有都市感的流行音乐。它与 AOR、放克、灵魂乐、爵士融合和迪斯科相交，并非一种严格、统一的曲风。今天的听众也会通过再版、唱片收藏和网络传播重新认识这些作品。</p><div class="guide-grid"><div><h3>1970s · 土壤</h3><p>はっぴいえんど、シュガー・ベイブ与创作歌手的实践，为日语流行音乐提供了新的表达。这里将部分唱片列为源流或邻近语境，不把所有作品都归入 City Pop。</p></div><div><h3>1980s · 交汇</h3><p>歌手、作词家、作曲家与编曲家的合作形成了密集的音乐网络。图谱把不同署名拆开，帮助你发现同一位创作者连接的作品。</p></div><div><h3>从唱片走向人</h3><p>先选一张熟悉的唱片，再点它的歌曲或参与者。沿“作曲”“编曲”等关系探索，比单纯按风格标签更能听出作品之间的联系。</p></div></div><h3>这是一份有边界的资料集</h3><p>首版为代表性收录，不是所有日本歌手、唱片或完整曲目表。发行年份尽量采用原始发行年，而非再版年份；每个条目和已核实的关系保留来源。没有可靠资料的署名不推测补齐。</p><h3>三种语言，同一份图谱</h3><p>界面与简介提供中文、英文、日文。作品标题保留正式原名；没有正式中文译名时使用原题或通行写法，不把说明性翻译当成官方名称。页面不提供未经授权的音乐、歌词或封面文件。</p>`,en:`<h2>City Pop has no single fixed boundary</h2><p>City Pop commonly describes urban-minded Japanese popular music associated with the late 1970s and 1980s. It overlaps with AOR, funk, soul, jazz fusion and disco rather than forming one strict genre. Reissues, record collecting and online circulation have brought these recordings to new audiences.</p><div class="guide-grid"><div><h3>1970s · Foundations</h3><p>Happy End, Sugar Babe and singer-songwriters opened new possibilities for Japanese-language pop. Some records here are roots or adjacent context, not blanket genre classifications.</p></div><div><h3>1980s · Collaborations</h3><p>Singers, lyricists, composers and arrangers form overlapping networks. Distinct credit relationships help uncover the people linking familiar records.</p></div><div><h3>Follow the credits</h3><p>Choose a record, follow a song and then its composer or arranger. This offers a way to discover connections beyond a genre label.</p></div></div><h3>A bounded collection</h3><p>This first edition is representative, not every Japanese artist, record or complete track listing. Years refer to original releases where established, not reissues. Documented entries and relationships retain sources. Unverified credits are omitted rather than guessed.</p><h3>Three languages, one graph</h3><p>Navigation and introductions are available in Chinese, English and Japanese. Official original titles are retained; descriptive translations are not official release names. No unauthorized audio, lyrics or cover files are hosted.</p>`,ja:`<h2>シティポップの境界は、一つではありません</h2><p>シティポップは、主に1970年代後半から1980年代の日本の都市的なポピュラー音楽を語る際に使われる言葉です。AOR、ファンク、ソウル、フュージョン、ディスコなどと重なり、厳密に統一されたジャンルではありません。再発盤、レコード収集、インターネットを通じて、新たな聴き手にも届いています。</p><div class="guide-grid"><div><h3>1970s · 源流</h3><p>はっぴいえんど、シュガー・ベイブ、シンガーソングライターたちの活動は、日本語のポップスに新しい可能性を開きました。源流や隣接する音楽として扱う作品も含みます。</p></div><div><h3>1980s · 交差</h3><p>歌手、作詞家、作曲家、編曲家が重なり合うネットワークを形成しました。クレジットの役割を分けることで、作品をつなぐ人物が見えてきます。</p></div><div><h3>クレジットをたどる</h3><p>一枚のレコードから楽曲へ、そして作曲家や編曲家へ。ジャンル名だけでは見つからないつながりを探索できます。</p></div></div><h3>収録範囲について</h3><p>初版は代表的な資料集であり、すべてのアーティスト、レコード、全曲目を網羅するものではありません。確認できる場合は再発年ではなく初出年を記載し、項目と関係に出典を残します。未確認のクレジットを推測で補いません。</p><h3>三つの言語、一つのグラフ</h3><p>画面と紹介文は中国語・英語・日本語に対応します。作品は正式な原題を保持し、説明のための訳を公式邦題・訳題として扱いません。無断の音源、歌詞、ジャケット画像は掲載していません。</p>`};$('#guide').innerHTML=content[lang]+`<h3>${t('coverage')}</h3><p>${nodes.length} ${t('nodes')} · ${edges.length} ${t('edges')} · 2026-09-30</p>`}
const canvas=$('#graph'),ctx=canvas.getContext('2d');
let width=800,height=600,yaw=.25,pitch=-.12,projected=[],autoRotate=false,animationId=0,lastFrame=0;
const pointers=new Map();let pinchDistance=0;
const degrees=new Map(nodes.map(n=>[n.id,edges.filter(e=>e.source===n.id||e.target===n.id).length]));
const cloudPoints=new Map(nodes.map((n,i)=>{const y=1-2*(i+.5)/nodes.length,angle=i*2.399963229728653,rad=Math.sqrt(1-y*y),depth=.6+.4*((i*37%101)/100);return[n.id,{x:Math.cos(angle)*rad*depth,y:y*depth,z:Math.sin(angle)*rad*depth}]}));
Object.assign(I.zh,{searchIndex:'搜索 / 索引',close:'关闭详情',rotate:'自动旋转',pauseRotation:'暂停旋转'});
Object.assign(I.en,{searchIndex:'Search / index',close:'Close details',rotate:'Auto rotate',pauseRotation:'Pause rotation'});
Object.assign(I.ja,{searchIndex:'検索 / インデックス',close:'詳細を閉じる',rotate:'自動回転',pauseRotation:'回転を停止'});
function layout(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;if(!width||!height)return;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;positions=filtered();const ids=new Set(positions.map(n=>n.id));links=edges.filter(e=>ids.has(e.source)&&ids.has(e.target));$('#empty').hidden=positions.length>0;$('#graph-count').textContent=`${positions.length} ${t('nodes')} · ${links.length} ${t('edges')}`;draw()}
function projectPoint(n){const p=cloudPoints.get(n.id),cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);const x=p.x*cy+p.z*sy,z0=-p.x*sy+p.z*cy,y=p.y*cp-z0*sp,z=p.y*sp+z0*cp;const perspective=3.2/(3.2-z),radius=Math.min(width*.39,height*.39)*scale;return{...n,x:width/2+x*radius*perspective,y:height/2+y*radius*perspective,z,r:(4+Math.min(12,Math.sqrt(degrees.get(n.id)||1)*2))*perspective*scale,depth:(z+1)/2}}
function draw(){const dpr=Math.min(devicePixelRatio||1,2);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,width,height);projected=positions.map(projectPoint).sort((a,b)=>a.z-b.z);const m=new Map(projected.map(p=>[p.id,p]));const focus=hover||selected;const neighbors=new Set(focus?[focus,...edges.filter(e=>e.source===focus||e.target===focus).flatMap(e=>[e.source,e.target])]:[]);
if(focus){for(const e of links){if(e.source!==focus&&e.target!==focus)continue;const a=m.get(e.source),b=m.get(e.target);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle='rgba(70,70,70,.24)';ctx.lineWidth=1;ctx.stroke()}}
for(const p of projected){const active=p.id===focus;ctx.globalAlpha=focus&&!neighbors.has(p.id)?.25:.25+p.depth*.75;ctx.beginPath();ctx.arc(p.x,p.y,Math.max(2,p.r),0,Math.PI*2);ctx.fillStyle='#262626';ctx.fill();if(active){ctx.globalAlpha=1;ctx.beginPath();ctx.arc(p.x,p.y,p.r+6,0,Math.PI*2);ctx.strokeStyle='#171717';ctx.lineWidth=1;ctx.stroke()}}
const boxes=[];for(const p of [...projected].sort((a,b)=>(b.id===focus?10:b.z)-(a.id===focus?10:a.z))){const active=p.id===focus,related=neighbors.has(p.id);let txt=label(p);ctx.font=`${active?'500':'400'} ${active?15:12}px 'Geist Mono','Noto Sans JP',monospace`;const maxW=Math.min(210,width-28);while(ctx.measureText(txt).width>maxW&&txt.length>3)txt=txt.slice(0,-2)+'…';const tw=ctx.measureText(txt).width;const x=Math.max(tw/2+8,Math.min(width-tw/2-8,p.x)),y=p.y-p.r-10,box={l:x-tw/2-3,r:x+tw/2+3,t:y-13,b:y+3};if(!active&&boxes.some(b=>box.l<b.r&&box.r>b.l&&box.t<b.b&&box.b>b.t))continue;if(y<18||y>height-20)continue;boxes.push(box);ctx.globalAlpha=active?1:focus&&!related?.2:Math.max(.35,.35+p.depth*.6);ctx.textAlign='center';ctx.fillStyle='#333333';ctx.fillText(txt,x,y)}ctx.globalAlpha=1;
}
function hit(e){const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;return [...projected].reverse().find(p=>Math.hypot(p.x-x,p.y-y)<=Math.max(p.r+5,12))}
function rotateLoop(now){if(!autoRotate)return;if(lastFrame&&view==='graph'&&!pointers.size){yaw+=Math.min(40,now-lastFrame)*.00008;draw()}lastFrame=now;animationId=requestAnimationFrame(rotateLoop)}
function stopRotation(){autoRotate=false;lastFrame=0;cancelAnimationFrame(animationId);$('#rotation-toggle').textContent=t('rotate');$('#rotation-toggle').setAttribute('aria-pressed','false')}
canvas.onpointerdown=e=>{stopRotation();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});drag={x:e.clientX,y:e.clientY};moved=false;hover=null;canvas.setPointerCapture(e.pointerId);if(pointers.size===2){const [a,b]=[...pointers.values()];pinchDistance=Math.hypot(a.x-b.x,a.y-b.y);moved=true}};
canvas.onpointermove=e=>{if(pointers.has(e.pointerId)){const prev=pointers.get(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const[a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(pinchDistance)scale=Math.max(.4,Math.min(2.5,scale*d/pinchDistance));pinchDistance=d;moved=true}else{const dx=e.clientX-prev.x,dy=e.clientY-prev.y;if(drag&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>4)moved=true;if(moved){yaw+=dx*.006;pitch+=dy*.006}}draw()}else{hover=hit(e)?.id;canvas.style.cursor=hover?'pointer':'grab';draw()}};
canvas.onpointerup=e=>{const wasMulti=pointers.size>1;pointers.delete(e.pointerId);if(!moved&&!wasMulti){const n=hit(e);if(n)select(n.id)}if(!pointers.size){drag=null;pinchDistance=0}};
canvas.onpointercancel=e=>{pointers.delete(e.pointerId);drag=null;pinchDistance=0;moved=true};canvas.onpointerleave=()=>{if(!pointers.size){hover=null;draw()}};
canvas.onwheel=e=>{e.preventDefault();scale=Math.max(.4,Math.min(2.5,scale*(e.deltaY>0?.92:1.08)));draw()};
$('#zoom-in').onclick=()=>{scale=Math.min(2.5,scale*1.2);draw()};$('#zoom-out').onclick=()=>{scale=Math.max(.4,scale/1.2);draw()};$('#reset').onclick=()=>{stopRotation();yaw=.25;pitch=-.12;scale=1;draw()};
$('#rotation-toggle').onclick=()=>{if(autoRotate){stopRotation();return}autoRotate=true;lastFrame=0;$('#rotation-toggle').textContent=t('pauseRotation');$('#rotation-toggle').setAttribute('aria-pressed','true');animationId=requestAnimationFrame(rotateLoop)};
$('#index-toggle').onclick=()=>{const open=document.body.classList.toggle('index-open');$('#index-toggle').setAttribute('aria-expanded',String(open));if(open)$('#search').focus()};
function closeDetail(){document.body.classList.remove('detail-open');selected=null;hover=null;render();canvas.focus()}
$('#close-detail').onclick=closeDetail;
$('#search').oninput=e=>{stopRotation();query=e.target.value.trim();render()};$('#type').onchange=e=>{stopRotation();type=e.target.value;render()};$('#decade').onchange=e=>{stopRotation();decade=e.target.value;render()};$('#clear').onclick=()=>{query=type=decade='';$('#search').value='';render()};$('#about-link').onclick=()=>{setView('guide');scrollTo({top:0,behavior:'smooth'})};
$$('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;try{localStorage.setItem('citypop-language',lang)}catch{};render()});let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(view==='graph')layout()},100)});
canvas.addEventListener('keydown',e=>{const k=e.key;if(k==='+'||k==='=')$('#zoom-in').click();else if(k==='-')$('#zoom-out').click();else if(k==='0')$('#reset').click();else if(k.startsWith('Arrow')){stopRotation();yaw+=k==='ArrowLeft'?-.12:k==='ArrowRight'?.12:0;pitch+=k==='ArrowUp'?-.12:k==='ArrowDown'?.12:0;draw()}else return;e.preventDefault()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('index-open');$('#index-toggle').setAttribute('aria-expanded','false');closeDetail()}});
render();

document.addEventListener('visibilitychange',()=>{if(document.hidden)stopRotation()});
